create table if not exists public.model_versions (id uuid primary key default gen_random_uuid(), version text unique not null, generated_at timestamptz not null, holdout_start date not null, validation_passed boolean not null default false, feature_names jsonb not null, metrics jsonb not null, assumptions jsonb not null, created_at timestamptz not null default now());
create table if not exists public.model_predictions (id bigint generated by default as identity primary key, model_version text not null references public.model_versions(version), symbol text not null check (symbol ~ '^[A-Z][A-Z0-9.-]{0,9}$'), as_of date not null, horizon_days integer not null default 90, boom_probability double precision not null check (boom_probability between 0 and 1), bust_probability double precision not null check (bust_probability between 0 and 1), expected_excess_return double precision not null, confidence double precision not null check (confidence between 0 and 1), factors jsonb not null, scores jsonb not null, generated_at timestamptz not null, unique (model_version, symbol, as_of));
create table if not exists public.backtest_results (id bigint generated by default as identity primary key, model_version text not null references public.model_versions(version), configuration jsonb not null, metrics jsonb not null, fold_results jsonb not null, created_at timestamptz not null default now());
alter table public.model_versions enable row level security; alter table public.model_predictions enable row level security; alter table public.backtest_results enable row level security;
create policy "validated model versions are readable" on public.model_versions for select using (validation_passed = true);
create policy "validated predictions are readable" on public.model_predictions for select using (exists (select 1 from public.model_versions where version = model_version and validation_passed = true));
create policy "validated backtests are readable" on public.backtest_results for select using (exists (select 1 from public.model_versions where version = model_version and validation_passed = true));
